"""Run the submission on JSONL input, return list of parsed output rows."""
import json, subprocess, sys, os

def run(lines, timeout=120):
    if isinstance(lines, str):
        data = lines.encode()
    elif isinstance(lines, bytes):
        data = lines
    else:
        data = ("\n".join(lines) + "\n").encode()
    p = subprocess.run([sys.executable, "-I", "/app/submission/main.py"],
                       input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                       timeout=timeout)
    assert p.returncode == 0, (p.returncode, p.stderr.decode()[:2000])
    txt = p.stdout.decode()
    assert p.stdout.decode().count("\n") == data.decode().count("\n") or txt.endswith("\n")
    rows = []
    for raw in txt.split("\n"):
        if raw == "":
            continue
        rows.append(json.loads(raw))
    return rows, p.stderr.decode()

def reqs(inp, join=True):
    return ("\n".join(inp) + "\n") if join else inp
PYEOF
